contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public payable {
        require(to != address(0));
        require(to != address(this));
        uint256 beforeBalanceTo = c.balanceOf(to);
        uint256 beforeBalanceThis = c.balanceOf(address(this));
        require(beforeBalanceThis >= amount);

        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalanceTo = c.balanceOf(to);
        uint256 afterBalanceThis = c.balanceOf(address(this));

        assert(!reverted && afterBalanceTo == beforeBalanceTo + amount && afterBalanceThis == beforeBalanceThis - amount);
    }

    receive() external payable {}
}

